Samir R: ok rough draft below, dropping into PR as a fenced block. feedback welcome.

Samir R: ```ts
import Redwood from '@redwood/inference-sdk';
const client = new Redwood({ apiKey: process.env.REDWOOD_KEY });

async function generate(prompt: string) {
  try {
    const res = await client.text.generate({
      model: 'rw/fast-1b', // choose a lower-latency tier
      input: prompt,
      max_tokens: 256,
    });
    return res.output_text;
  } catch (err: any) {
    if (err.status === 429) {
      // simple exponential backoff
      await new Promise(r => setTimeout(r, 1000));
      return generate(prompt);
    }
    throw err;
  }
}
```

